using System;
using System.Linq;
using Microsoft.Office.Tools;
using OfficeCliAgent.Core;
using Interop = Microsoft.Office.Interop.PowerPoint;

namespace OfficeCliAgent.PowerPoint
{
    /// <summary>
    /// Replace the template-generated ThisAddIn.cs with this file.
    /// (ThisAddIn.Designer.cs stays as generated by Visual Studio.)
    ///
    /// PowerPoint shows every presentation in its own window and a custom task pane belongs to
    /// one window, so the add-in keeps one pane per document window (see WindowPaneRegistry) and
    /// creates it the first time the window becomes active.
    /// </summary>
    public partial class ThisAddIn
    {
        private const string PaneTitle = "OfficeCLI Agent for PowerPoint";
        private const int PaneWidth = 420;

        private PowerPointOps _ops;
        private readonly WindowPaneRegistry<CustomTaskPane> _panes = new WindowPaneRegistry<CustomTaskPane>();
        /// <summary>Last state chosen with the ribbon toggle; panes of newly opened windows start this way.</summary>
        private bool _wantVisible = true;

        internal bool IsPaneVisible
        {
            get
            {
                var pane = FindPane(ActiveWindow());
                return pane != null && SafeVisible(pane);
            }
        }

        private void ThisAddIn_Startup(object sender, EventArgs e)
        {
            try
            {
                _ops = new PowerPointOps(Application);
                var events = (Interop.EApplication_Event)Application;
                events.WindowActivate += (presentation, window) => OnWindowChanged(window);
                // New and opened presentations get their window before it is activated.
                events.AfterNewPresentation += presentation => OnWindowChanged(ActiveWindow());
                events.AfterPresentationOpen += presentation => OnWindowChanged(ActiveWindow());
                OnWindowChanged(ActiveWindow());
            }
            catch (Exception ex)
            {
                Log.Write("powerpoint: startup failed: " + ex);
            }
        }

        private void ThisAddIn_Shutdown(object sender, EventArgs e)
        {
            _panes.Dispose();
        }

        internal void TogglePane()
        {
            var window = ActiveWindow();
            if (window == null) return;
            var pane = FindPane(window) ?? CreatePane(window);
            if (pane == null) return;
            _wantVisible = !SafeVisible(pane);
            pane.Visible = _wantVisible;
        }

        private void OnWindowChanged(Interop.DocumentWindow window)
        {
            try
            {
                PruneClosedWindows();
                if (window == null) return;
                if (FindPane(window) == null)
                {
                    var pane = CreatePane(window);
                    if (pane != null) pane.Visible = _wantVisible;
                }
                Ribbon?.Invalidate();
            }
            catch (Exception ex)
            {
                Log.Write("powerpoint: pane update failed: " + ex);
            }
        }

        private CustomTaskPane CreatePane(Interop.DocumentWindow window)
        {
            var hwnd = window.HWND;
            var controller = new AgentController(_ops);
            CustomTaskPane pane;
            try
            {
                pane = CustomTaskPanes.Add(controller.Pane, PaneTitle, window);
            }
            catch (Exception ex)
            {
                Log.Write($"powerpoint: cannot create the task pane for window {hwnd}: {ex.Message}");
                controller.Dispose();
                return null;
            }
            pane.Width = PaneWidth;
            pane.VisibleChanged += (_, __) => Ribbon?.Invalidate();
            _panes.Add(hwnd, pane, controller);
            Log.Write($"addin: task pane created for window {hwnd} ({_panes.Count} open)");
            return pane;
        }

        private CustomTaskPane FindPane(Interop.DocumentWindow window)
        {
            if (window == null) return null;
            var hwnd = window.HWND;
            // The handle check guards against Windows reusing a closed window's HWND for a new window.
            return _panes.TryGet(hwnd, out var pane) && WindowHandleOf(pane) == hwnd ? pane : null;
        }

        /// <summary>Drop the panes of closed windows: VSTO keeps them in CustomTaskPanes only until it notices.</summary>
        private void PruneClosedWindows()
        {
            foreach (var dead in _panes.Prune(pane => WindowHandleOf(pane) != null))
            {
                try { CustomTaskPanes.Remove(dead); } catch (Exception) { /* already gone */ }
            }
        }

        /// <summary>HWND of the window the pane lives in, or null once that window is closed or the pane is disposed.</summary>
        private int? WindowHandleOf(CustomTaskPane pane)
        {
            try
            {
                if (!CustomTaskPanes.Any(p => ReferenceEquals(p, pane))) return null;
                if (pane.Control == null || pane.Control.IsDisposed) return null;
                // PowerPoint throws here once the window is gone (COM object deleted).
                return (pane.Window as Interop.DocumentWindow)?.HWND;
            }
            catch (Exception) { return null; }
        }

        private static bool SafeVisible(CustomTaskPane pane)
        {
            try { return pane.Visible; }
            catch (ObjectDisposedException) { return false; }
        }

        /// <summary>Null in Backstage / when no presentation window is open (ActiveWindow throws then).</summary>
        private Interop.DocumentWindow ActiveWindow()
        {
            try { return Application.Windows.Count > 0 ? Application.ActiveWindow : null; }
            catch (Exception) { return null; }
        }

        internal Ribbon Ribbon { get; private set; }

        protected override Microsoft.Office.Core.IRibbonExtensibility CreateRibbonExtensibilityObject()
        {
            // Runs before ThisAddIn_Startup, so the ribbon labels already see the Office UI language.
            try { UiLanguage.Initialize(Application.LanguageSettings.LanguageID[Microsoft.Office.Core.MsoAppLanguageID.msoLanguageIDUI]); }
            catch (Exception ex) { Log.Write("addin: UI language detection failed: " + ex.Message); }
            Ribbon = new Ribbon();
            return Ribbon;
        }

        #region VSTO generated code

        /// <summary>
        /// Required method for Designer support - do not modify
        /// the contents of this method with the code editor.
        /// </summary>
        private void InternalStartup()
        {
            this.Startup += new System.EventHandler(ThisAddIn_Startup);
            this.Shutdown += new System.EventHandler(ThisAddIn_Shutdown);
        }

        #endregion
    }
}
